+async fn gap_finish(process: WireProcess, bank: &Bank, expected_success: bool) -> Vec<Value> {
+    let WireProcess { mut child, input, mut output, mut frames, directory } = process;
+    drop(input);
+    let drain = async {
+        while let Some(line) = output.next_line().await.unwrap() {
+            let mut raw = fs::OpenOptions::new().create(true).append(true).open(directory.join("stdout.txt")).unwrap();
+            writeln!(raw, "{line}").unwrap();
+            if let Ok(frame) = serde_json::from_str::<Value>(&line) {
+                frames.push(frame);
+            }
+        }
+    };
+    let (status, ()) = tokio::join!(wait_exit(bank, &mut child), drain);
+    assert_eq!(status.success(), expected_success, "{}", fs::read_to_string(bank.directory.join("stderr.txt")).unwrap());
+    fs::write(bank.directory.join("wire-frames.json"), serde_json::to_vec_pretty(&frames).unwrap()).unwrap();
+    frames
+}
